'use strict';

// Fixed, non-configurable cap protects all recursive AST walkers, including
// ASTs supplied directly by callers rather than generated by parse().
const MAX_DEPTH = 100;
const assertDepth = depth => {
  if (depth > MAX_DEPTH) {
    throw new SyntaxError('Brace pattern exceeds maximum nesting depth (100)');
  }
};
module.exports = { MAX_DEPTH, assertDepth };
